local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["7800151ae469873d"] = { "Onore e lodi saranno tuoi, se saprai prenderli, {class}! Cerca Kurden Bloodclaw nel Royal Quarter di questa città.", "." },
  ["7803a292e7f48651"] = { "Salute, soldato. Sei qui per aiutare la causa?", "." },
  ["78055707c5addf73"] = { "Ah, mi ricordo di te. Sei quell<o/a> che chiedeva di quel tale Stalvan. Hai poi trovato quello che cercavi?", "." },
  ["78087075043b67de"] = { "Cosa? Una cosina così piccola e fragile mi chiama? Aggiungerò le tue ossa al mio trono, {race}!!", "." },
  ["7809246c1d5c082f"] = { "The Vault, a ⟦Ironforge=Forgiardente⟧, è la banca più vicina che troverai da queste parti.", "." },
  ["78197a05136b2a3e"] = { "Gubber, non so pescare.", "." },
  ["781b1cb3b2b18041"] = { "AIUTO!!!!", "." },
  ["78216e7f714f4a89"] = { "Riverito.", "." },
  ["7823cbaf8cbcc274"] = { "L'antico regno di Lordaeron è pieno di pericoli. Raccomandiamo prudenza a chiunque osi avventurarsi nelle terre ormai in rovina delle ⟦Tirisfal Glades=Radure di Tirisfal⟧. Se proprio devi, cerca ⟦Undercity=Sepulcra⟧: sono i cortili superiori il luogo che cerchi.", "." },
  ["782d2dbca8c760b8"] = { "Questa torta di ciliegie è così buona che farebbe piangere uno gnomo adulto.", "." },
  ["7833064e289abb75"] = { "Con la ⟦Stone of Relu=Pietra di Relu⟧ potrò liberare i segreti nascosti del mio fossile e anche di quello di Remtravel, da ⟦Darkshore=Rivafosca⟧, {name}.", "." },
  ["78334f40b9ccdce7"] = { "Degli intrusi stanno distruggendo le nostre uova! Fermi!!", "." },
  ["7834e1a0f8ba6e0e"] = { "Che l'evento abbia inizio!", "." },
  ["7838ebd6924f5683"] = { "Ma certo che non c'è alcun pericolo che tutto prenda fuoco ed esploda come un'enorme bomba all'elio. Questo gioiellino ti porterà a ⟦Undercity=Sepulcra⟧ più in fretta e con più sicurezza di qualsiasi nave, e il panorama è davvero mozzafiato. A proposito di fiato: a bordo dello zeppelin è vietato fumare, ed è proibito lanciare incantesimi di fuoco durante il viaggio.", "." },
  ["783e99538e9c9375"] = { "Dimmi, te la senti di affrontare la prova che ho preparato per te? Gli spiriti mi dicono che la supererai, ma hai fede in loro o in te?", "." },
  ["783e9ee25feca4e9"] = { "Aprila. Dobbiamo sbrigarci. Quei Ferroscuro li fiuto a un miglio di distanza, e una cosa te la posso dire: STANNO ARRIVANDO!", "." },
  ["783ff6e80725f13b"] = { "La mia vista si è offuscata, ma esistono molti modi di vedere...", "." },
  ["7840947f73845348"] = { "Terenthis, Raene mi ha mandato a cercarti. Le ⟦Sentinels=Sentinelle⟧ hanno bisogno d'aiuto a ⟦Ashenvale=Valtetra⟧.", "." },
  ["7844ae0217eb2979"] = { "Spalmami la cenere sul viso come pittura di guerra!", "." },
  ["7846f8f039762a5a"] = { "No! Non può essere...", "." },
  ["785a78c7e3099649"] = { "Ho perso il mio segnalatore e me ne serve un altro, Scooty.", "." },
  ["785b492612a1073f"] = { "A me, miei servitori!", "." },
  ["785c39bc98e580f2"] = { "Il ⟦Stormpike Graveyard=Cimitero dei Piccatonante⟧ è scavato nelle montagne, oltre il ponte a est di Dun Baldar.\n\nAl momento nessuna delle due parti lo controlla.", "." },
  ["786008308cd20e67"] = { "VIENI A CAPO JANEIRO. TI ASPETTO, SMOTTS...", "." },
  ["7869187b0077b2cc"] = { "Non che dubiti delle tue capacità, ma vorrei che svolgessi un compito per me. Chiamala una prova di buona fede...", "." },
  ["7870c84427eb4750"] = { "Oh, magnifico.", "." },
  ["787299a314e9883e"] = { "Sii <guarito/guarita>, <sacerdote/sacerdotessa>.", "." },
  ["7876056419e218a4"] = { "Annalise... Hai ragione. N-non posso farlo. Devo trovare un'altra strada.", "." },
  ["787b620f41c50e8e"] = { "Grazie, signora Brightbeard!", "." },
  ["787cfcc884d3157c"] = { "<Usa il dispositivo di trascrizione per ricavare un calco.>", "." },
  ["78822593fba7e6b2"] = { "Uldum è una struttura di ricerca dei Creatori, impegnati da sempre a migliorare la biosfera di Azeroth. Le informazioni specifiche sul loro lavoro relativo a Uldum sono riservate agli individui che possiedono le Plates of Uldum nei loro set di dischi.\n\nGli archivi di dati all'interno del complesso di Uldum sono stati programmati per trattare esperimenti e raccolte di dati specifici: consultali per informazioni dettagliate.", "." },
  ["788b56ca7c085a61"] = { "Qualcosa di diverso!!!", "." },
  ["78940420937377e2"] = { "Perché tu scappa? Noi fa di tuo cadavere Flagello.", "." },
  ["789a75ceccecfb60"] = { "Un'altra domanda della prima catena: RISPOSTA!", "." },
  ["789da6a778a2e2f2"] = { "No, qui no...", "." },
  ["789f549d50160e6f"] = { "Sacerdote", "." },
  ["78ba86f2df4c7b82"] = { "Il sangue investe %s, che viene irradiato!", "." },
  ["78badfc416ca537c"] = { "Ti sei <guadagnato/guadagnata> il privilegio di addestrarti con un istruttore di grado superiore. Va' dal mio amico Roxxik, laggiù.", "." },
  ["78bb0662bf44689e"] = { "Ho bisogno di addestramento, Keryn.", "." },
  ["78bc90d0706cf79f"] = { "Noi esuli di Gnomeregan ci troviamo in guai ancora peggiori, perché le nostre riserve di stoffa stanno finendo! Forse puoi aiutarci, eh?!\n\nPortami tutti i pezzi di stoffa in più che hai, per aiutarci a ricostituire le scorte. Donandoli, ti guadagnerai il rispetto e la fiducia degli gnomi di ogni dove. E questo non si compra con il denaro! Be', con la stoffa sì, a quanto pare, ma non è questo il punto...", "." },
  ["78c1898eab5ab4c2"] = { "Henze è salvo, {name}? Ci sei <riuscito/riuscita>?\n\nTra la tua abilità con le armi e il potere della Luce, immagino che la ⟦Heroes' Vigil=Veglia degli Eroi⟧ sia al sicuro da qualunque minaccia dei Defias, ma spetta al re e ai suoi consiglieri dirlo.", "." },
  ["78c254176eeefc9f"] = { "Perché sei qui, {name}? Hai del piombo negli stivali?\n\nHai gli ordini d'assalto: il maestro di guerra Garrick ne ha bisogno nel ⟦Field of Strife=Pian della Discordia⟧ per poter lanciare l'attacco! Vai!", "." },
  ["78c26d654b23318f"] = { "Qualcosa per me, {class}?", "." },
  ["78c4f1a1139c585c"] = { "L'⟦Whitereach Post=Accampamento di Manto Bianco⟧ è nato come un piccolo campo di caccia... Ora tutti vogliono aprire bottega e stabilirsi qui.\n\n<Motega scrolla le spalle>", "." },
  ["78c8940e16a5f96d"] = { "%s osserva il proprio sangue che inizia ad agitarsi, mentre l'astuzia del raptor lo pervade.", "." },
  ["78d13ad5323eb683"] = { "Perdonami.", "." },
  ["78ddc793e7280802"] = { "L'ingresso della ⟦Wailing Caverns=Caverna dei Lamenti⟧ si trova all'⟦Lushwater Oasis=Oasi Acquefertili⟧, a sud-ovest del ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧.", "." },
  ["78e678eb738b9156"] = { "Mi aspetta un'altra gloriosa giornata di pesca, Khara. Meglio che mi muova.", "." },
  ["78ec493e99e78248"] = { "Questi atti eroici non significano nulla, {class}. Il tuo futuro è segnato e la tua anima è condannata alla servitù!", "." },
  ["78eeb473e532efbe"] = { "Guarda sopra di te; thara dormil dorah...", "." },
  ["78f1cfc141ced234"] = { "Cosa sta succedendo a tutti? Ho... freddo...", "." },
  ["78f387791a6b66af"] = { "{class}, grazie agli sforzi di molti siamo riusciti a raccogliere tutte le bende di telarunica che l'⟦Alliance=Alleanza⟧ ritiene necessarie per il conflitto imminente. Fossi in te, chiederei ad altri qui intorno se hanno ancora raccolte da completare.", "." },
  ["78f6197fcc0def20"] = { "Capitano Redpath! Come hai potuto abbandonarci!", "." },
  ["78f73009e26027b5"] = { "Bleah... quello non è un pesce!", "." },
  ["78f9c293e27bfccd"] = { "Non dirmelo! Shhh! Sei qui per il Brandicenere?!? Sì... Sì... No! Errore mio.\n\nCosa posso fare per te, {race}?", "." },
  ["78ff4985d12f3511"] = { "Sei riuscit<o/a> a trovare Merrin? Ti ha dato notizie per me?", "." },
})
